mapper.select:
select laa.id, laa.equity_name, laa.units, laa.name, laa.icon, laa.type, laa.detail_type, laa.award, laa.use_num, laa.limit_type, laa.limit_num, laa.status, laa.create_user_id, laa.update_user_id, laa.create_time, laa.update_time from la_activity_award laa
and laa.is_delete = 0
and laa.name like concat('%',#{param.name},'%')
and laa.equity_name like concat('%',#{param.equityName},'%')
and laa.type = #{param.type}
and laa.award like concat('%',#{param.award},'%')
and laa.use_num = #{param.useNum}
and laa.limit_type = #{param.limitType}
and laa.limit_num = #{param.limitNum}
and laa.status = #{param.status}
and laa.create_user_id = #{param.createUserId}
and laa.update_user_id = #{param.updateUserId}
and laa.detail_type = #{param.detailType}
order by laa.id desc
